import json,base64,hashlib,os
from pathlib import Path
r=Path('/dataset/shaoshitong/search-r1-rl/bapo-e1-instruct300-ray-titlefix-20261006');changes={'verify_launch.py': {'old': '970f3231a2e8029599bb712fc8ed19fa2bbdab0dcc079bdac28f19a837a1b675', 'raw': ''}, 'test_freeze_scalability.py': {'old': 'aea3110a2ee34d2341cc3d130b386260e682e418a4a06bec9aec1b255186a4d5', 'raw': ''}}
assert not list((r/'runs').iterdir()) and not (r/'logs/launch-approval.json').exists()
archive=r/'deployment-archive/prior35-before-durable';archive.mkdir(parents=True)
p=r/'logs/tools-manifest.json';old=p.read_bytes();(archive/'tools-manifest.json').write_bytes(old)
for name,item in changes.items():
 p=r/'tools'/name;before=p.read_bytes();assert hashlib.sha256(before).hexdigest()==item['old']
 (archive/name).write_bytes(before);raw=base64.b64decode(item['raw']);tmp=p.with_name(name+'.reviewed-tmp')
 with tmp.open('xb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
 os.replace(tmp,p);p.chmod(0o755)
m={'source_commit':'484c0b30fa73fa5354bdb3452f007134ec5db13f','files':{p.name:hashlib.sha256(p.read_bytes()).hexdigest()for p in (r/'tools').iterdir()if p.is_file()}}
assert len(m['files'])==35
p=r/'logs/tools-manifest.json';tmp=p.with_name('tools-manifest.reviewed-tmp')
with tmp.open('x') as f:f.write(json.dumps(m,sort_keys=True,indent=2)+'\n')
os.replace(tmp,p)
print(json.dumps({'status':'REVIEWED_TWO_DELTA_DEPLOYED_NO_JOB','manifest_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'archive':str(archive)}))
